#import "SRStore.h"
#include <sqlite3.h>
NSString *SRJSON(id object) { NSData *d=[NSJSONSerialization dataWithJSONObject:object options:NSJSONWritingSortedKeys error:nil];if(!d)@throw [NSException exceptionWithName:@"InvalidJSON" reason:@"Invalid data" userInfo:nil];return [[NSString alloc]initWithData:d encoding:NSUTF8StringEncoding]; }
id SRParse(NSString *json){if(![json isKindOfClass:NSString.class]||json.length>16*1024*1024)@throw [NSException exceptionWithName:@"InvalidJSON" reason:@"Invalid data" userInfo:nil];id value=[NSJSONSerialization JSONObjectWithData:[json dataUsingEncoding:NSUTF8StringEncoding] options:0 error:nil];if(!value)@throw [NSException exceptionWithName:@"InvalidJSON" reason:@"Invalid data" userInfo:nil];return value;}
NSString *SRIdentifier(NSString *prefix){return [prefix stringByAppendingString:[NSUUID.UUID.UUIDString.lowercaseString stringByReplacingOccurrencesOfString:@"-" withString:@""]];}
@implementation SRStore {sqlite3 *_db;}
- (instancetype)init {if((self=[super init])){NSURL *support=[NSFileManager.defaultManager URLsForDirectory:NSApplicationSupportDirectory inDomains:NSUserDomainMask].firstObject;_directory=[support URLByAppendingPathComponent:@"SecureReel" isDirectory:YES];NSError *error;[NSFileManager.defaultManager createDirectoryAtURL:_directory withIntermediateDirectories:YES attributes:@{NSFileProtectionKey:NSFileProtectionCompleteUntilFirstUserAuthentication} error:&error];if(error)@throw [NSException exceptionWithName:@"Storage" reason:@"Archive unavailable" userInfo:nil];NSURL *dbURL=[_directory URLByAppendingPathComponent:@"checkpoints.sqlite"];if(sqlite3_open(dbURL.fileSystemRepresentation,&_db)!=SQLITE_OK||sqlite3_exec(_db,"PRAGMA journal_mode=WAL; PRAGMA synchronous=FULL; CREATE TABLE IF NOT EXISTS documents(kind TEXT NOT NULL,id TEXT NOT NULL,json TEXT NOT NULL,PRIMARY KEY(kind,id));",nullptr,nullptr,nullptr)!=SQLITE_OK)@throw [NSException exceptionWithName:@"Database" reason:@"Checkpoints unavailable" userInfo:nil];}return self;}
- (NSArray*)documents:(NSString*)kind {@synchronized(self){sqlite3_stmt *statement=nullptr;NSMutableArray *values=[NSMutableArray array];if(sqlite3_prepare_v2(_db,"SELECT json FROM documents WHERE kind=? ORDER BY id",-1,&statement,nullptr)!=SQLITE_OK)@throw [NSException exceptionWithName:@"Database" reason:@"Checkpoint read failed" userInfo:nil];sqlite3_bind_text(statement,1,kind.UTF8String,-1,SQLITE_TRANSIENT);int status;while((status=sqlite3_step(statement))==SQLITE_ROW){const char *json=(const char*)sqlite3_column_text(statement,0);[values addObject:SRParse([NSString stringWithUTF8String:json])];}sqlite3_finalize(statement);if(status!=SQLITE_DONE)@throw [NSException exceptionWithName:@"Database" reason:@"Checkpoint read failed" userInfo:nil];return values;}}
- (void)put:(NSDictionary*)document kind:(NSString*)kind identifier:(NSString*)identifier {@synchronized(self){NSString *json=SRJSON(document);sqlite3_stmt *statement=nullptr;if(sqlite3_prepare_v2(_db,"INSERT INTO documents(kind,id,json) VALUES(?,?,?) ON CONFLICT(kind,id) DO UPDATE SET json=excluded.json",-1,&statement,nullptr)!=SQLITE_OK)@throw [NSException exceptionWithName:@"Database" reason:@"Checkpoint write failed" userInfo:nil];sqlite3_bind_text(statement,1,kind.UTF8String,-1,SQLITE_TRANSIENT);sqlite3_bind_text(statement,2,identifier.UTF8String,-1,SQLITE_TRANSIENT);sqlite3_bind_text(statement,3,json.UTF8String,-1,SQLITE_TRANSIENT);int status=sqlite3_step(statement);sqlite3_finalize(statement);if(status!=SQLITE_DONE)@throw [NSException exceptionWithName:@"Database" reason:@"Checkpoint write failed" userInfo:nil];}}
- (void)removeKind:(NSString*)kind identifier:(NSString*)identifier {@synchronized(self){sqlite3_stmt *statement=nullptr;sqlite3_prepare_v2(_db,"DELETE FROM documents WHERE kind=? AND id=?",-1,&statement,nullptr);sqlite3_bind_text(statement,1,kind.UTF8String,-1,SQLITE_TRANSIENT);sqlite3_bind_text(statement,2,identifier.UTF8String,-1,SQLITE_TRANSIENT);sqlite3_step(statement);sqlite3_finalize(statement);}}
- (void)dealloc {if(_db)sqlite3_close(_db);}
@end
